// First-person input and view are separate from the mission simulation.
export function movementVector(yaw,forward,right){let x=-Math.sin(yaw)*forward+Math.cos(yaw)*right,z=-Math.cos(yaw)*forward-Math.sin(yaw)*right,len=Math.hypot(x,z);return len?{x:x/len,z:z/len}:{x:0,z:0}}
export class FirstPerson{
 constructor(world,{onInteract,onNotice,isBlocked}){this.world=world;world.fps=this;this.yaw=0;this.pitch=0;this.eye=1.7;this.bob=0;this.zoom=false;this.onInteract=onInteract;this.onNotice=onNotice;this.isBlocked=isBlocked;this.locked=false;this.drag=null;this.touch=false;this.aim=null;this.lastAim=0;let c=world.renderer.domElement;
 document.addEventListener('pointerlockchange',()=>{this.locked=document.pointerLockElement===c;document.body.classList.toggle('fps-locked',this.locked);if(!this.locked)this.onNotice('Mouse bebas. Klik Lanjutkan menjelajah untuk kembali bermain.');this.updateOverlay()});document.addEventListener('pointerlockerror',()=>{this.onNotice('Pointer lock tidak tersedia. Tahan dan geser area game untuk melihat sekeliling.');document.body.classList.add('fps-drag-mode');this.updateOverlay()});document.addEventListener('mousemove',e=>{if(this.locked&&!this.isBlocked())this.look(e.movementX,e.movementY)});
 c.addEventListener('pointerdown',e=>{if(e.button!==0)return;if(this.isBlocked())return;if(e.pointerType==='touch'){this.touch=true;this.drag={x:e.clientX,y:e.clientY};c.setPointerCapture(e.pointerId);this.updateOverlay()}else if(this.locked)this.pick();else this.enter()});c.addEventListener('pointermove',e=>{if(this.drag){this.look(e.clientX-this.drag.x,e.clientY-this.drag.y);this.drag={x:e.clientX,y:e.clientY}}});c.addEventListener('pointerup',()=>this.drag=null);c.addEventListener('pointercancel',()=>this.drag=null);c.addEventListener('contextmenu',e=>e.preventDefault());c.addEventListener('wheel',e=>{e.preventDefault();this.zoom=e.deltaY<0},{passive:false});window.addEventListener('blur',()=>this.exit());this.updateOverlay()}
 look(dx,dy){this.yaw-=dx*.0022;this.pitch=Math.max(-1.45,Math.min(1.45,this.pitch-dy*.0022))}
 enter(){if(this.isBlocked())return;let c=this.world.renderer.domElement;try{let p=c.requestPointerLock?.();p?.catch(()=>{this.touch=true;this.updateOverlay();this.onNotice('Klik dan geser untuk melihat sekeliling.');this.enableDragFallback()});if(!c.requestPointerLock)this.enableDragFallback()}catch{this.enableDragFallback()}}
 enableDragFallback(){const c=this.world.renderer.domElement;this.touch=true;document.body.classList.add('fps-drag-mode');if(this.fallback)return;this.fallback=true;c.addEventListener('pointerdown',e=>{if(e.button===0&&!this.isBlocked()){this.drag={x:e.clientX,y:e.clientY};c.setPointerCapture(e.pointerId)}});this.updateOverlay()}
 exit(){if(document.pointerLockElement)document.exitPointerLock();this.drag=null}
 updateOverlay(){let overlay=document.querySelector('#fps-entry');if(overlay)overlay.hidden=this.locked||this.touch}
 view(local,dt,walking,jet){let camera=this.world.camera;this.bob+=(walking?dt*9:0);let height=this.eye+(jet?3:0)+(walking?Math.sin(this.bob)*.035:0);camera.position.set(local.x,height,local.z);camera.rotation.order='YXZ';camera.rotation.set(this.pitch,this.yaw,0,'YXZ');let target=this.zoom?42:78;if(Math.abs(camera.fov-target)>.1){camera.fov+=(target-camera.fov)*.18;camera.updateProjectionMatrix()}}
 updateAim(t){if(t-this.lastAim<.15)return;this.lastAim=t;const w=this.world;w.mouse.set(0,0);w.ray.setFromCamera(w.mouse,w.camera);w.ray.far=70;const objects=[...w.meshes,...w.remote.values(),w.petModel].filter(o=>o&&o.visible!==false&&o.userData.record?.id!==w.selfId);let hit=w.ray.intersectObjects(objects,true).find(h=>h.distance<70&&(h.object.userData.record||h.object.userData.records));let record=hit&&(hit.object.userData.records?.[hit.instanceId]||hit.object.userData.record);if(record&&this.locked&&!this.isBlocked()&&['ground','road','river'].includes(record.type)&&hit.distance<2)record=null;if(record){this.aim={...record,distance:hit.distance};document.querySelector('#aim-name').textContent=record.name;document.querySelector('#aim-distance').textContent=`${hit.distance.toFixed(0)} unit · E / klik untuk periksa`}else{this.aim=null;document.querySelector('#aim-name').textContent='Jelajahi kota';document.querySelector('#aim-distance').textContent='Arahkan bidikan ke objek untuk informasi'}w.ray.far=Infinity}
 pick(){if(this.isBlocked())return;if(this.aim)this.onInteract(this.aim);else this.onNotice('Arahkan bidikan ke objek yang ingin diperiksa.')}
}
